<script setup lang="ts">import {useAuthStore} from '../stores/auth';import {RouterLink,useRouter} from 'vue-router';const auth=useAuthStore(),router=useRouter();function out(){auth.signOut();router.push('/')}</script><template><div class="page"><div class="center"><div class="card"><div class="eyebrow">Perfil</div><h1 style="font-size:34px">{{auth.user?.name}}</h1><p>{{auth.user?.email}}</p><div class="source"><div class="source-logo">{{auth.user?.platform.name.slice(0,1)}}</div><div><strong>{{auth.user?.platform.name}}</strong><div style="font-size:12px;color:#718078">Sua plataforma de origem</div></div></div><div class="actions"><RouterLink class="btn ghost" to="/dashboard">Dashboard</RouterLink><button class="btn danger" @click="out">Sair</button></div></div></div></div></template>
